import assert from 'node:assert/strict'
import { readFile, writeFile, access } from 'node:fs/promises'
import { join } from 'node:path'
import { createHash } from 'node:crypto'
const root = '/Users/ryanbetts/.t3/worktrees/pardner/t3-selfhost-cursor-cloud'
const { ExpectedOperations, hash } = await import(root + '/support/acceptance/expected-operations.js')
const { candidateFingerprint } = await import(root + '/support/acceptance/candidate.js')
const read = async path => JSON.parse(await readFile(path, 'utf8'))
const final = join(root, 'output/verification/cloud-final-108-20261105')
const before = await read(join(final, 'candidate.before.json'))
const after = await read(join(final, 'candidate.after.json'))
const current = await candidateFingerprint(root)
assert.equal(before.sha256, after.sha256); assert.equal(before.sha256, current.sha256)
const results = []
for (const [log, count] of [['verify.log', 1], ['qualification.log', 20]]) {
  const output = (await readFile(join(final, log), 'utf8')).match(/Acceptance scenario reports: (.+)/)?.[1].trim()
  assert.ok(output, `No acceptance result in ${log}`)
  const summary = await read(join(output, 'summary.json')), candidate = await read(join(output, 'candidate.json'))
  assert.equal(candidate.sha256, current.sha256); assert.equal(summary.candidateSha256, current.sha256)
  assert.equal(summary.scenarioPassed, true); assert.equal(summary.repeat, count); assert.equal(summary.reports.length, count)
  const seeds = []
  for (let i = 0; i < count; i++) {
    const item = summary.reports[i], directory = join(output, `seed-${i+1}`)
    const report = await read(join(directory, 'report.json')), snapshot = await read(join(directory, 'snapshot.json'))
    assert.equal(item.seed, i+1); assert.equal(report.seed, i+1); assert.equal(item.hash, hash(report))
    assert.equal(report.scenarioPassed, true); assert.equal(report.candidateSha256, current.sha256)
    assert.equal(snapshot.schemaVersion, 5)
    assert.equal(report.manifest.intents.length, Object.keys(report.manifest.receipts).length)
    assert.deepEqual(report.fixture, {tasks:100, comments:400, scriptedOperations:200})
    assert.deepEqual(report.limits, {localAckMs:2500, localVisibleMs:2000, offlineStartMs:6000, convergenceMs:10000})
    const expected = new ExpectedOperations()
    for (const intent of report.manifest.intents) expected.intend(intent, report.manifest.expectedReplicas[intent.operationId])
    let receiptMax = 0
    for (const [id, {receipt, elapsedMs}] of Object.entries(report.manifest.receipts)) {
      const intent = expected.intents.get(id)
      assert.ok(intent); assert.equal(receipt.requestId, id)
      assert.equal(receipt.operationId, `op-${hash([id, hash({ type:intent.type, actorId:intent.actorId, payload:intent.payload })])}`)
      expected.acknowledge(intent, receipt, elapsedMs); receiptMax = Math.max(receiptMax, elapsedMs)
    }
    const verified = expected.verify(snapshot)
    assert.equal(report.verified.length, 3)
    assert.equal(report.heads.length, 3)
    for (const heads of report.heads) assert.deepEqual(heads, snapshot.heads)
    for (const result of report.verified) assert.deepEqual(result, verified)
    const maxima = {}
    for (const timing of report.timings) maxima[timing.kind] = Math.max(maxima[timing.kind] ?? 0, timing.elapsed)
    assert.ok(maxima['agent-effect-ack']<=2500); assert.ok(receiptMax<=2500); assert.ok(maxima['local-ack']<=2500); assert.ok(maxima['local-ui-visible']<=2000)
    assert.ok(maxima['offline-start']<=6000); assert.ok(maxima.convergence<=10000)
    assert.equal(report.agentEvidence.length, 2)
    for (const agent of report.agentEvidence) {
      assert.equal(agent.inbox.length, 1); assert.equal(agent.inbox[0].acknowledged, 1); assert.equal(agent.inbox[0].complete, 1); assert.equal(agent.effects.length, 1)
      assert.ok(agent.events.some(event => event.checkpoint === 'context-read' && event.descriptionLength>500 && event.commentCount>=4 && event.historyCount>=5))
    }
    for (const file of ['failure.json', 'cleanup-errors.json']) await assert.rejects(access(join(directory,file)), {code:'ENOENT'})
    seeds.push({seed:report.seed, reportHash:item.hash, reportFileSha256:createHash('sha256').update(await readFile(join(directory,'report.json'))).digest('hex'), snapshotFileSha256:createHash('sha256').update(await readFile(join(directory,'snapshot.json'))).digest('hex'), snapshotHash:verified.snapshotHash, schemaVersion:snapshot.schemaVersion, intendedOperationCount:report.manifest.intents.length, operationCount:verified.operationCount, receiptMaxMs:receiptMax, timingSampleCounts:Object.fromEntries([...new Set(report.timings.map(t=>t.kind))].map(kind=>[kind,report.timings.filter(t=>t.kind===kind).length])), maxima})
  }
  results.push({log, output, count, seeds})
}
await writeFile(join(final,'audit.json'),JSON.stringify({candidate:current.sha256,node:process.version,results},null,2))
console.log('AUDIT_PASSED '+current.sha256+' reports=21')
